if (ctx.event == null) { ctx.event = [:]; }
String ds = ctx.event.dataset instanceof String ? ctx.event.dataset : '';
if (!ds.startsWith('openconsole.')) { ds = ctx.message == 'audit' ? 'openconsole.audit' : 'openconsole.app'; ctx.event.dataset = ds; }
if (ds == 'openconsole.audit') {
  if (ctx.event.kind == null) { ctx.event.kind = 'event'; }
  if (ctx.openconsole == null) { ctx.openconsole = [:]; }
  String a = ctx.event.action instanceof String ? ctx.event.action : '';
  if (ctx.openconsole.verb == null && a != '') {
    String o = null;
    for (String s : ['success', 'denied', 'failed', 'rate_limited', 'locked']) {
      if (a.endsWith('.' + s)) { o = s; a = a.substring(0, a.length() - s.length() - 1); break; }
    }
    String rt = ctx.openconsole.resource_type instanceof String ? ctx.openconsole.resource_type : '';
    if (rt == 'ingresses') { rt = 'ingress'; } else if (rt.endsWith('s') && rt != 'settings') { rt = rt.substring(0, rt.length() - 1); }
    Map renamed = ['login': 'user.login', 'login.azure': 'user.login', 'change_password': 'user.change_password',
      'user.password_reset': 'user.reset_password', 'user.auto_provision': 'user.create', 'secret.yaml.view': 'secret.view_yaml',
      'recording.settings.update': 'settings.update', 'recording.evicted': 'recording.evict',
      'view.save': 'saved_view.create', 'view.share': 'saved_view.share', 'view.delete': 'saved_view.delete', 'view.change': 'saved_view.update',
      'session.revoke_all': 'session.revoke', 'admin.update_groups': 'user.update', 'admin.update_roles': 'group.update',
      'admin.add_permission': 'permission.create', 'admin.delete_permission': 'permission.delete'];
    if (a == 'list' || a == 'get' || a == 'logs') {
      a = rt + '.' + a;
    } else if (a == 'pod.exec.start' || a == 'pod.exec.end') {
      ctx.openconsole.phase = a.substring(9);
      a = 'pod.exec';
    } else if (a.endsWith('.apply')) {
      a = rt + '.apply';
    } else if (renamed.containsKey(a)) {
      a = renamed.get(a);
    } else if (a.startsWith('admin.') && (rt == 'user' || rt == 'group' || rt == 'role')) {
      a = rt + '.' + a.substring(6);
    }
    int i = a.lastIndexOf('.');
    if (i > 0) { ctx.openconsole.resource_type = a.substring(0, a.indexOf('.')); }
    String v = i > 0 ? a.substring(i + 1) : a;
    ctx.openconsole.verb = v;
    ctx.openconsole.outcome = o == null ? 'success' : o;
    ctx.event.action = a;
    Map types = ['list': 'access', 'get': 'access', 'logs': 'access', 'view_yaml': 'access', 'reveal': 'access', 'view': 'access',
      'download': 'access', 'export': 'access', 'create': 'creation', 'import': 'creation', 'delete': 'deletion', 'evict': 'deletion',
      'purge': 'deletion', 'revoke': 'deletion', 'login': 'start'];
    if (ctx.event.type == null) {
      if (v == 'exec') { ctx.event.type = [ctx.openconsole.phase == 'end' ? 'end' : 'start']; }
      else { ctx.event.type = [types.containsKey(v) ? types.get(v) : 'change']; }
    }
  }
  if (ctx.event.outcome == null && ctx.openconsole.outcome instanceof String) {
    ctx.event.outcome = ctx.openconsole.outcome == 'success' ? 'success' : 'failure';
  }
